-- Seed gerado por assets/gerador-avaliacao-discursiva (não editar à mão; fora do Git).
-- Rodar depois de database/2026-10-01-respostas-discursivas.sql. Idempotente.
-- A avaliação nasce BLOQUEADA (ativo = false): o professor libera no índice de atividades.
do $$
declare
  v_aula bigint;
  v_atividade bigint;
begin
  select a.id into v_aula from public.aulas a join public.materia m on m.id = a.materia_id
    where m.descricao = 'Fundamentos de UI / UX' and a.numero = 6
    order by a.id limit 1;
  if v_aula is null then
    raise exception 'Aula 06 da matéria não encontrada';
  end if;

  insert into public.atividade (nome_atividade, status, aula_id, descricao, pagina,
      total_itens, ativo)
    values ('Atividade Prática — Aula 06', 'PENDENTE', v_aula, 'Atividade — Atividade Prática — Aula 06 (20 questões discursivas)',
      '/MATERIAIS/TECNICO-INFORMATICA-INTERNET/FUNDAMENTOS-DE-UI-UX/ATIVIDADES/ATIVIDADE-PRATICA-AULA-06.html', 20, false)
    on conflict (pagina) do update set aula_id = excluded.aula_id,
      descricao = excluded.descricao, total_itens = excluded.total_itens
    returning id into v_atividade;

  delete from public.topico_discursivo where atividade_id = v_atividade;
  insert into public.topico_discursivo (atividade_id, item, topico, enunciado, pontos,
      resposta_esperada, criterios) values
      (v_atividade, 1, 1, 'Defina User Interface (UI) com as suas palavras.', 0.2, 'A User Interface (UI) é a camada que conecta a pessoa ao sistema e traduz as suas intenções em operações da máquina. Não é só a parte bonita da tela.', 'Nota cheia: define a UI como camada ou ponte de comunicação e tradução entre pessoa e máquina, com as palavras do aluno. Metade: define a UI apenas como parte visual ou tela, sem a ideia de tradução ou conexão. Zero: em branco, errado ou fora do tema.'),
      (v_atividade, 1, 2, 'Explique por que a UI é chamada de ponte entre humano e máquina.', 0.4, 'A UI recebe a entrada do usuário (toque, tecla, fala ou gesto) e devolve uma saída compreensível (tela, áudio ou vibração). Como a pessoa pensa em ideias e o computador só processa sinais lógicos, a UI traduz nos dois sentidos, em via de mão dupla.', 'Nota cheia: explica a tradução nos dois sentidos (entrada e saída) entre o pensamento humano e o processamento da máquina. Metade: diz que a UI conecta pessoa e máquina, mas não explica a tradução nem os dois sentidos. Zero: em branco, errado ou fora do tema.'),
      (v_atividade, 1, 3, 'Dê um exemplo de entrada (input) e um de saída (output) em uma tela de agendamento.', 0.4, 'Entrada: tocar no horário desejado, digitar o nome ou escolher a data. Saída: a mensagem "Agendamento confirmado" ou a tela com o horário marcado.', 'Nota cheia: dá um exemplo correto de entrada e um de saída, dentro da tela de agendamento. Metade: dá só um dos dois exemplos corretos, ou exemplos genéricos sem relação com o agendamento. Zero: em branco, errado ou fora do tema.'),
      (v_atividade, 2, 1, 'Descreva o caminho do toque até a resposta da tela.', 0.2, 'O toque do dedo no botão é captado pelo sensor da tela, o sistema processa o comando de confirmar e a interface devolve a resposta (mudança na tela, mensagem, som ou vibração). O caminho tem entrada, processamento e saída.', 'Nota cheia: descreve as etapas do toque até a resposta, na ordem (entrada, processamento e saída). Metade: cita o toque e a resposta, sem as etapas intermediárias. Zero: em branco, errado ou fora do tema.'),
      (v_atividade, 2, 2, 'Explique o que é um feedback visível ou sonoro e por que ele é necessário.', 0.4, 'Feedback é a resposta perceptível da interface (visual, sonora ou vibratória) que confirma ao usuário que a ação foi recebida ou executada. Ele é necessário para que a pessoa saiba que o sistema reagiu.', 'Nota cheia: define feedback como retorno perceptível da interface e explica a necessidade de confirmar a ação ao usuário. Metade: define feedback sem explicar a necessidade, ou explica a necessidade sem a definição. Zero: em branco, errado ou fora do tema.'),
      (v_atividade, 2, 3, 'Indique um problema de uso que a falta de feedback causa.', 0.4, 'Sem retorno, o usuário toca várias vezes no botão, o que pode gerar agendamentos duplicados, ou desiste achando que o sistema travou.', 'Nota cheia: indica um problema concreto de uso (toques repetidos, dúvida se o sistema reagiu, duplicidade ou desistência) causado pela falta de feedback. Metade: cita um problema genérico, como confusão, sem relacioná-lo à falta de feedback. Zero: em branco, errado ou fora do tema.'),
      (v_atividade, 3, 1, 'Defina a CLI a partir da forma como o usuário a utiliza.', 0.2, 'A CLI é a interface em que o usuário digita comandos de texto no terminal, com sintaxe exata, e o sistema processa cada comando de imediato.', 'Nota cheia: define a CLI como comandos de texto digitados, com processamento imediato, a partir da forma de uso. Metade: define de forma incompleta, por exemplo só "linha de comando", sem o texto digitado. Zero: em branco, errado ou fora do tema.'),
      (v_atividade, 3, 2, 'Cite duas vantagens da CLI apresentadas na aula.', 0.4, 'Duas vantagens da aula: consome pouca memória; opera com extrema velocidade; permite automatizar tarefas repetitivas em scripts; oferece precisão sem distrações gráficas.', 'Nota cheia: cita duas vantagens corretas apresentadas na aula. Metade: cita uma vantagem correta, ou duas com uma delas errada ou fora da aula. Zero: em branco, errado ou fora do tema.'),
      (v_atividade, 3, 3, 'Cite duas limitações da CLI e explique o impacto delas para um usuário leigo.', 0.4, 'Duas limitações da aula: curva de aprendizado íngreme; necessidade de lembrar o comando exato; falta de sugestões visuais. Para o usuário leigo, o impacto é não conseguir operar o equipamento sem estudo formal e cometer erros que o sistema não explica.', 'Nota cheia: cita duas limitações da aula e explica o impacto delas para o usuário leigo. Metade: cita duas limitações sem o impacto, ou uma limitação com o impacto explicado. Zero: em branco, errado ou fora do tema.'),
      (v_atividade, 4, 1, 'Indique a modalidade recomendada.', 0.2, 'Recomenda-se a CLI (linha de comando), acessada remotamente, por ser a modalidade usada para administrar servidores sem recursos gráficos.', 'Nota cheia: indica a CLI e a relaciona ao servidor remoto ou à gestão sem recursos gráficos. Metade: indica a CLI sem relacioná-la ao servidor remoto nem ao uso diário. Zero: indica outra modalidade (GUI, VUI ou NUI), ou fica em branco.'),
      (v_atividade, 4, 2, 'Explique a relação entre a CLI e a automação de tarefas por scripts.', 0.4, 'Scripts são sequências de comandos de CLI executadas automaticamente. A CLI é a base para automatizar tarefas repetitivas, o que poupa o trabalho diário do administrador.', 'Nota cheia: explica que a CLI permite automatizar tarefas por scripts, com comandos repetidos executados sem intervenção. Metade: cita scripts ou automação sem explicar a relação com a CLI. Zero: em branco, errado ou fora do tema.'),
      (v_atividade, 4, 3, 'Descreva o que o administrador precisa conhecer antes de usar essa modalidade.', 0.4, 'O administrador precisa conhecer a sintaxe dos comandos e os parâmetros exatos, saber usar o terminal com acesso remoto seguro (como SSH) e entender o que cada comando altera no servidor.', 'Nota cheia: cita pelo menos dois conhecimentos (sintaxe, parâmetros, acesso remoto seguro ou efeito dos comandos). Metade: cita apenas um conhecimento. Zero: em branco, errado ou fora do tema.'),
      (v_atividade, 5, 1, 'Explique o que é uma interface gráfica (GUI).', 0.2, 'A GUI é a interface gráfica, com janelas, ícones, menus e ponteiro, que representa objetos e tarefas na tela e permite manipulá-los com o cursor.', 'Nota cheia: define a GUI com representação visual e manipulação por ponteiro ou cursor. Metade: define a GUI só como tela com imagens ou janelas, sem a manipulação. Zero: em branco, errado ou fora do tema.'),
      (v_atividade, 5, 2, 'Explique o conceito WIMP com as suas palavras.', 0.4, 'WIMP é a sigla de Windows (janelas), Icons (ícones), Menus e Pointer (ponteiro), os elementos básicos de uma GUI.', 'Nota cheia: explica os quatro elementos (janelas, ícones, menus e ponteiro) com as palavras do aluno. Metade: cita os quatro elementos sem explicá-los, ou explica apenas três. Zero: em branco, errado ou fora do tema.'),
      (v_atividade, 5, 3, 'Justifique se a proposta do colega atende ao público leigo.', 0.4, 'A proposta não atende ao público leigo, porque comandos de texto exigem memorizar sintaxe. A GUI, com metáforas visuais como pastas, lixeira e botões, é mais adequada a quem não é técnico.', 'Nota cheia: conclui que a proposta não atende e justifica pela necessidade de memorizar comandos, contrastando com o reconhecimento visual da GUI. Metade: conclui corretamente, mas sem justificativa, ou com justificativa genérica. Zero: aprova a proposta sem justificar, ou fica em branco.'),
      (v_atividade, 6, 1, 'Explique o princípio de reconhecimento visual na GUI.', 0.2, 'Reconhecer é mais fácil do que lembrar: as opções ficam visíveis na tela e a pessoa escolhe sem memorizar comandos.', 'Nota cheia: explica que as opções ficam visíveis e que o usuário reconhece em vez de lembrar. Metade: menciona apenas que as opções aparecem, sem o contraste com memorizar. Zero: em branco, errado ou fora do tema.'),
      (v_atividade, 6, 2, 'Explique o que é sobrecarga visual e cite um efeito dela no usuário.', 0.4, 'Sobrecarga visual é o excesso de botões e elementos sem hierarquia. Ela deixa o usuário perdido e confuso, levando a demora, erros ou abandono da tarefa.', 'Nota cheia: define sobrecarga visual e cita um efeito no usuário (confusão, perda, erro ou abandono). Metade: define sem citar efeito, ou cita efeito sem definir. Zero: em branco, errado ou fora do tema.'),
      (v_atividade, 6, 3, 'Proponha como menus ou painéis podem reduzir a sobrecarga da tela.', 0.4, 'Agrupar os botões em menus ou painéis por função (por exemplo, agendar, consultar e cancelar), usar hierarquia visual que destaque a ação principal e separar as tarefas em janelas ou abas.', 'Nota cheia: propõe agrupamento ou hierarquia por menus ou painéis e justifica a redução da sobrecarga. Metade: propõe menus ou painéis sem justificar. Zero: em branco, errado ou fora do tema.'),
      (v_atividade, 7, 1, 'Defina a interface de voz (VUI).', 0.2, 'A VUI é a interface de voz, em que a pessoa controla o sistema e faz consultas falando de forma natural, e o sistema responde em áudio ou na tela.', 'Nota cheia: define a VUI como interação por fala natural, com resposta do sistema. Metade: define só como comando de voz, sem a fala natural ou sem a resposta. Zero: em branco, errado ou fora do tema.'),
      (v_atividade, 7, 2, 'Descreva as quatro etapas de processamento de um comando de voz, na ordem em que acontecem.', 0.4, 'Na ordem: 1) captura da fala (o microfone capta e filtra ruídos); 2) conversão áudio-texto; 3) interpretação semântica (o sistema descobre a intenção e os parâmetros); 4) resposta sintetizada (executa a ação e retorna em áudio ou tela).', 'Nota cheia: lista as quatro etapas, na ordem correta. Metade: lista três etapas corretas, na ordem, ou as quatro com uma trocada de posição. Zero: em branco, errado ou fora do tema.'),
      (v_atividade, 7, 3, 'Explique por que sotaques e ruídos causam erros de interpretação.', 0.4, 'Sotaques e ruídos alteram o som captado pelo microfone. Como o algoritmo foi treinado com variações comuns, a conversão do áudio em texto ou a interpretação da intenção pode sair errada.', 'Nota cheia: explica que sotaque e ruído alteram o áudio captado e levam a uma conversão ou interpretação errada. Metade: cita sotaque ou ruído como causa, sem explicar o mecanismo. Zero: em branco, errado ou fora do tema.'),
      (v_atividade, 8, 1, 'Aponte o problema de privacidade dessa situação.', 0.2, 'Falar dados bancários em voz alta dentro do ônibus expõe informações sensíveis a outras pessoas que estão por perto.', 'Nota cheia: aponta que a fala expõe dados sensíveis a terceiros no ambiente. Metade: aponta privacidade de forma genérica, sem relacioná-la ao ambiente. Zero: em branco, errado ou fora do tema.'),
      (v_atividade, 8, 2, 'Explique como o ruído do ambiente afeta a interface de voz.', 0.4, 'O ruído do ambiente, como motor e conversas, é captado junto com a fala. Isso atrapalha a captura e a conversão áudio-texto e gera erros de interpretação do comando.', 'Nota cheia: explica que o ruído se mistura à fala e causa erro de captura ou interpretação. Metade: cita o ruído como problema, sem explicar o efeito. Zero: em branco, errado ou fora do tema.'),
      (v_atividade, 8, 3, 'Indique a modalidade que você recomendaria e justifique a escolha.', 0.4, 'Recomenda-se a interface gráfica no celular, ou a digitação em texto, em local privado, para que a pessoa leia e digite os dados sem expô-los ao público e sem depender do ruído.', 'Nota cheia: indica uma modalidade adequada (GUI ou texto) e justifica pela privacidade e pelo ruído. Metade: indica a modalidade sem justificar, ou justifica sem indicar uma modalidade. Zero: em branco, errado ou fora do tema.'),
      (v_atividade, 9, 1, 'Defina a interface natural (NUI).', 0.2, 'A NUI é a interface natural, em que a pessoa interage com o próprio corpo (toque direto, gestos no ar, olhar ou biometria), sem o intermediário mecânico de teclado e mouse.', 'Nota cheia: define a NUI como interação com o corpo, sem teclado e mouse. Metade: define sem citar o corpo ou sem citar a ausência de intermediário mecânico. Zero: em branco, errado ou fora do tema.'),
      (v_atividade, 9, 2, 'Cite dois sensores ou modalidades da NUI apresentados na aula.', 0.4, 'Dois exemplos da aula: multi-touch direto (telas capacitivas); gestos no espaço (câmeras e sensores de profundidade); biometria facial ou digital; rastreamento ocular.', 'Nota cheia: cita dois sensores ou modalidades corretos e apresentados na aula. Metade: cita um correto, ou dois com um deles errado. Zero: em branco, errado ou fora do tema.'),
      (v_atividade, 9, 3, 'Explique por que essa interface é chamada de "natural".', 0.4, 'A interface é chamada de natural porque aproveita gestos e reflexos que a pessoa já usa no mundo físico, como tocar, apontar, pegar e olhar, o que exige pouco aprendizado.', 'Nota cheia: relaciona o nome "natural" aos gestos e reflexos já praticados no mundo físico. Metade: diz que é natural sem explicar o motivo. Zero: em branco, errado ou fora do tema.'),
      (v_atividade, 10, 1, 'Identifique o ponto fraco da NUI apresentado na aula.', 0.2, 'O ponto fraco é o cansaço físico em gestos longos e repetidos, além da menor precisão em tarefas finas.', 'Nota cheia: identifica o cansaço físico (ou a menor precisão fina) como ponto fraco da NUI. Metade: diz apenas que é difícil de usar, sem indicar o ponto fraco específico. Zero: em branco, errado ou fora do tema.'),
      (v_atividade, 10, 2, 'Explique por que gestos longos e repetidos causam cansaço.', 0.4, 'Gestos longos exigem manter o braço sustentado no ar, e a repetição de movimentos seguidos causa fadiga muscular. Em um formulário longo, essa repetição agrava o cansaço.', 'Nota cheia: explica que manter o braço no ar e repetir movimentos causa fadiga. Metade: diz que cansa, sem explicar o motivo. Zero: em branco, errado ou fora do tema.'),
      (v_atividade, 10, 3, 'Proponha uma alternativa de interface para o formulário e justifique.', 0.4, 'Usar um formulário com teclado físico ou digitação tradicional nos campos de texto, ou ditado por voz, mantendo a NUI apenas para toques simples. A justificativa é menos cansaço e mais precisão na digitação.', 'Nota cheia: propõe uma alternativa adequada (teclado, voz ou formulário visual) e a justifica com cansaço ou precisão. Metade: propõe alternativa sem justificar. Zero: em branco, errado ou fora do tema.'),
      (v_atividade, 11, 1, 'Indique a modalidade recomendada.', 0.2, 'Recomenda-se a interface gráfica (GUI), com tela, para editar a planilha no computador de escritório.', 'Nota cheia: indica a GUI. Metade: indica a GUI sem citar a tela ou a visão. Zero: indica outra modalidade (CLI, VUI ou NUI), ou fica em branco.'),
      (v_atividade, 11, 2, 'Justifique a escolha com base na precisão exigida e no uso da visão.', 0.4, 'A planilha exige precisão fina com números pequenos e uso intenso da visão. A GUI permite ver e selecionar células com o ponteiro, enquanto a voz não oferece precisão nem permite conferir vários números ao mesmo tempo.', 'Nota cheia: justifica pela precisão exigida e pelo uso da visão, comparando com a modalidade. Metade: justifica com apenas um dos dois fatores. Zero: em branco, errado ou fora do tema.'),
      (v_atividade, 11, 3, 'Explique o que acontece quando a modalidade escolhida não combina com a tarefa.', 0.4, 'A pessoa fica exausta, comete erros graves e perde produtividade. A tarefa fica lenta e cheia de enganos.', 'Nota cheia: descreve uma consequência concreta para a tarefa (cansaço, erro ou lentidão). Metade: cita erro de forma genérica, sem relação com a tarefa. Zero: em branco, errado ou fora do tema.'),
      (v_atividade, 12, 1, 'Associe cada pessoa a uma modalidade (texto, gráfica ou voz).', 0.2, 'A técnica, sentada diante do computador, usa texto (CLI) ou gráfica (GUI). A motorista usa voz (VUI). O cliente na loja usa a interface gráfica (GUI), na tela do celular.', 'Nota cheia: associa as três pessoas a modalidades adequadas (técnica: texto ou gráfica; motorista: voz; cliente: gráfica). Metade: acerta duas das três associações. Zero: em branco, errado ou fora do tema.'),
      (v_atividade, 12, 2, 'Explique o ponto forte da modalidade escolhida para cada pessoa.', 0.4, 'Técnica: precisão e rapidez do texto, ou a visão focada da tela. Motorista: voz, que deixa as mãos e os olhos livres para dirigir. Cliente: a tela, em que vê a capa do álbum e toca no ícone Play, sem precisar de comandos.', 'Nota cheia: explica o ponto forte da modalidade escolhida para cada uma das três pessoas. Metade: explica o ponto forte de duas pessoas. Zero: em branco, errado ou fora do tema.'),
      (v_atividade, 12, 3, 'Explique por que nenhuma modalidade serve bem a todas as situações.', 0.4, 'Cada modalidade tem limites: o texto exige memória e teclado; a gráfica exige visão e mãos; a voz perde privacidade e sofre com o ruído. Como o contexto muda a cada situação, nenhuma modalidade serve bem a todos.', 'Nota cheia: cita o limite de pelo menos duas modalidades e conclui que o contexto decide a escolha. Metade: diz que depende do contexto, sem citar os limites. Zero: em branco, errado ou fora do tema.'),
      (v_atividade, 13, 1, 'Ordene as quatro modalidades pelo esforço de aprendizado, do menor para o maior.', 0.2, 'Do menor para o maior esforço de aprendizado: NUI, VUI, GUI e CLI.', 'Nota cheia: ordem exata NUI, VUI, GUI e CLI. Metade: três posições corretas, ou troca de duas posições vizinhas. Zero: em branco, errado ou fora do tema.'),
      (v_atividade, 13, 2, 'Justifique a escolha da modalidade mais simples para esse cliente.', 0.4, 'A modalidade mais simples para esse cliente é a NUI (toque direto no celular), porque usa gestos que a pessoa já pratica no mundo físico e não exige aprender comandos. Aceitar a VUI se a resposta justificar pela fala natural.', 'Nota cheia: escolhe a NUI (ou a VUI, justificada) e cita o esforço mínimo ou os gestos já conhecidos. Metade: escolhe uma modalidade adequada sem justificar. Zero: escolhe a CLI, ou fica em branco.'),
      (v_atividade, 13, 3, 'Cite um recurso de acessibilidade que ajude esse cliente.', 0.4, 'Recursos como botões grandes, fonte ampliada, alto contraste, leitor de tela ou comando por voz. Basta um recurso correto e pertinente a esse cliente.', 'Nota cheia: cita um recurso de acessibilidade correto e pertinente ao cliente idoso. Metade: cita um recurso genérico, como "ser simples". Zero: em branco, errado ou fora do tema.'),
      (v_atividade, 14, 1, 'Explique o papel do leitor de tela para a pessoa cega.', 0.2, 'O leitor de tela traduz os elementos gráficos da tela (botões, textos e opções) em áudio sintetizado, o que permite à pessoa cega navegar sem ver.', 'Nota cheia: explica que o leitor transforma os elementos gráficos em áudio para a pessoa cega navegar. Metade: diz apenas que "lê a tela", sem explicar o processo. Zero: em branco, errado ou fora do tema.'),
      (v_atividade, 14, 2, 'Explique por que botões grandes e espaçados ajudam quem tem tremores.', 0.4, 'Botões grandes e espaçados evitam toques acidentais causados pelos tremores, porque a pessoa acerta o alvo com mais facilidade.', 'Nota cheia: relaciona o tamanho e o espaçamento a evitar toques acidentais causados pelos tremores. Metade: cita o tamanho sem relacioná-lo aos tremores. Zero: em branco, errado ou fora do tema.'),
      (v_atividade, 14, 3, 'Explique por que um aviso sonoro precisa de alternativa visual para pessoas surdas.', 0.4, 'A pessoa surda não ouve o aviso sonoro. Por isso, a informação precisa de uma alternativa visual, como texto, ícone, legenda ou vibração.', 'Nota cheia: explica que a pessoa surda não percebe o som e que a informação precisa de alternativa visual. Metade: diz que é "para acessibilidade", sem relacionar à surdez. Zero: em branco, errado ou fora do tema.'),
      (v_atividade, 15, 1, 'Coloque as quatro etapas do ciclo de interação na ordem correta.', 0.2, 'Na ordem: 1) o usuário define mentalmente uma intenção; 2) envia o comando pela modalidade da interface; 3) o sistema processa os dados da instrução; 4) a interface devolve um feedback visível ou sonoro.', 'Nota cheia: as quatro etapas, na ordem correta. Metade: três etapas corretas, na ordem. Zero: em branco, errado ou fora do tema.'),
      (v_atividade, 15, 2, 'Indique em qual etapa do ciclo o problema pode estar e explique o motivo.', 0.4, 'O problema pode estar na etapa 4 (a interface não devolveu feedback) ou na etapa 3 (o sistema não processou o comando). Como a tela não muda, a falta de resposta visível indica que o retorno não chegou ao usuário.', 'Nota cheia: indica uma etapa plausível (3 ou 4) e explica o motivo ligado à tela que não muda. Metade: indica uma etapa sem motivo claro. Zero: em branco, errado ou fora do tema.'),
      (v_atividade, 15, 3, 'Proponha um feedback para essa etapa.', 0.4, 'Mostrar um indicador de carregamento ao tocar em Agendar e, em seguida, uma mensagem de confirmação ou de erro, visual e sonora.', 'Nota cheia: propõe feedback visível (carregamento, confirmação ou mensagem de erro) relacionado à etapa indicada. Metade: propõe feedback genérico, sem relação com a etapa. Zero: em branco, errado ou fora do tema.'),
      (v_atividade, 16, 1, 'Descreva a diferença entre a forma como as pessoas pensam e a forma como o computador processa dados.', 0.2, 'As pessoas pensam em ideias, imagens, palavras e sentimentos. O computador processa apenas sinais binários, zeros e uns.', 'Nota cheia: contrasta o pensamento humano (ideias, imagens, palavras) com o processamento lógico e binário. Metade: cita apenas uma das duas partes. Zero: em branco, errado ou fora do tema.'),
      (v_atividade, 16, 2, 'Explique o papel da UI como camada tradutora.', 0.4, 'A UI traduz as intenções humanas em operações lógicas do sistema e devolve a resposta de forma compreensível à pessoa, nos dois sentidos.', 'Nota cheia: explica a UI como tradutora nos dois sentidos (entrada e saída). Metade: diz que a UI traduz, sem mencionar os dois sentidos. Zero: em branco, errado ou fora do tema.'),
      (v_atividade, 16, 3, 'Dê um exemplo de intenção humana traduzida em uma operação do sistema.', 0.4, 'Exemplo: a pessoa toca em "Cancelar consulta", que expressa a intenção de desmarcar, e o sistema executa a operação de exclusão do agendamento.', 'Nota cheia: dá um exemplo correto de intenção humana traduzida em operação do sistema. Metade: dá exemplo genérico, sem a operação. Zero: em branco, errado ou fora do tema.'),
      (v_atividade, 17, 1, 'Defina interface multimodal.', 0.2, 'Interface multimodal é aquela que combina duas ou mais modalidades (como olhar, voz, toque ou texto) na mesma interação.', 'Nota cheia: define a interface multimodal como combinação de duas ou mais modalidades. Metade: diz apenas "várias formas de interação", sem a ideia de combinação. Zero: em branco, errado ou fora do tema.'),
      (v_atividade, 17, 2, 'Explique por que o sistema pode se adaptar ao canal mais conveniente naquele momento.', 0.4, 'O sistema percebe o contexto (por exemplo, a pessoa está dirigindo ou com as mãos ocupadas) e escolhe o canal mais conveniente e seguro naquele momento, sem obrigar a um único meio.', 'Nota cheia: explica que o sistema escolhe o canal conforme o contexto e a conveniência do momento. Metade: diz que é "mais flexível", sem a adaptação ao contexto. Zero: em branco, errado ou fora do tema.'),
      (v_atividade, 17, 3, 'Cite um risco de privacidade ou de segurança dessa proposta e como reduzi-lo.', 0.4, 'Risco: a captura do olhar e da voz pode expor a privacidade ou permitir uma compra por terceiros. Redução: exigir uma confirmação extra, como senha ou biometria, e pedir autorização expressa para o uso da câmera e do microfone.', 'Nota cheia: cita um risco concreto (privacidade ou segurança) e uma forma de reduzi-lo. Metade: cita o risco sem medida de redução, ou com medida genérica. Zero: em branco, errado ou fora do tema.'),
      (v_atividade, 18, 1, 'Registre se você concorda ou não com a afirmação.', 0.2, 'A posição esperada é não concordar com a afirmação, porque as telas seguem necessárias. Qualquer posição fundamentada é aceita, desde que seja clara.', 'Nota cheia: registra uma posição clara e, de preferência, não concorda com a afirmação, em linha com a aula. Metade: registra uma posição pouco clara. Zero: em branco, errado ou fora do tema.'),
      (v_atividade, 18, 2, 'Apresente dois argumentos, com base na aula, para justificar a sua posição.', 0.4, 'Argumentos da aula: tarefas distintas exigem modalidades diferentes; telas são necessárias para leitura, análise e privacidade; voz e gestos devem atuar de forma híbrida, sem eliminar as telas.', 'Nota cheia: dois argumentos corretos da aula, com as palavras do aluno. Metade: um argumento correto. Zero: em branco, errado ou fora do tema.'),
      (v_atividade, 18, 3, 'Proponha uma solução híbrida para um caso concreto de uso.', 0.4, 'Exemplo: em uma consulta pelo celular, a pessoa toca na data (NUI) e dita o nome (VUI), com a confirmação final na tela. Qualquer caso concreto com duas modalidades combinadas e uma razão serve.', 'Nota cheia: propõe uma solução híbrida com duas modalidades para um caso concreto, com a razão da combinação. Metade: propõe solução híbrida sem caso concreto ou sem razão. Zero: em branco, errado ou fora do tema.'),
      (v_atividade, 19, 1, 'Diga qual é o primeiro passo do consultor antes de sugerir elementos de tela.', 0.2, 'O primeiro passo é diagnosticar o contexto: analisar quem é o público-alvo e onde o produto será usado, antes de sugerir qualquer elemento de tela.', 'Nota cheia: diz que o primeiro passo é entender o público-alvo e o local de uso. Metade: diz apenas "entender o cliente", sem o público e o local. Zero: em branco, errado ou fora do tema.'),
      (v_atividade, 19, 2, 'Explique por que o público-alvo e o local de uso mudam a escolha da interface.', 0.4, 'Público e local mudam a escolha. Idosos precisam de botões grandes; um motorista precisa de voz; um ambiente barulhento ou público exige privacidade e tela. A modalidade ideal depende de quem usa e onde usa.', 'Nota cheia: explica, com pelo menos um exemplo, que o público e o local alteram a modalidade. Metade: afirma que mudam, sem exemplo. Zero: em branco, errado ou fora do tema.'),
      (v_atividade, 19, 3, 'Descreva como verificar o contraste e a compatibilidade com leitor de tela.', 0.4, 'Verificar o contraste entre texto e fundo e o tamanho da fonte, e testar a navegação com leitor de tela, conferindo se os elementos têm rótulo e se a ordem de leitura é lógica.', 'Nota cheia: cita o contraste e o teste com leitor de tela, com a forma de conferir. Metade: cita só um dos dois. Zero: em branco, errado ou fora do tema.'),
      (v_atividade, 20, 1, 'Indique a modalidade principal e a modalidade secundária.', 0.2, 'A modalidade principal é a NUI (toque direto no celular, com botões grandes). A secundária pode ser a GUI (calendário visual) ou a VUI (confirmação por voz).', 'Nota cheia: indica a NUI (ou toque direto) como principal e uma secundária adequada (GUI ou VUI). Metade: indica corretamente apenas uma das duas. Zero: em branco, errado ou fora do tema.'),
      (v_atividade, 20, 2, 'Justifique a modalidade principal com base no contexto de uso pelo celular.', 0.4, 'Os idosos usam o celular com o dedo, e o toque direto aproveita gestos já conhecidos. Botões grandes e um calendário visual nítido facilitam a marcação do horário.', 'Nota cheia: justifica a modalidade principal com o uso pelo celular e o toque direto. Metade: justifica sem considerar o contexto do celular. Zero: em branco, errado ou fora do tema.'),
      (v_atividade, 20, 3, 'Explique como a acessibilidade entra na sua decisão.', 0.4, 'A acessibilidade entra com botões grandes e espaçados, contraste adequado, leitor de tela, alternativa visual para avisos sonoros e confirmação por voz para quem tem dificuldade motora.', 'Nota cheia: cita pelo menos dois recursos de acessibilidade ligados ao público idoso e à decisão tomada. Metade: cita apenas um recurso. Zero: em branco, errado ou fora do tema.');
end $$;
